  &lt;span&gt;critical ${tTwo ? `=T.INV.2T(${tAlpha.toFixed(2)}, ${tDf})` : tRight ? `=T.INV(${(1 - tAlpha).toFixed(2)}, ${tDf})` : `=T.INV(${tAlpha.toFixed(2)}, ${tDf})`}&lt;/span&gt;
&lt;/div&gt;`

13.4 Type I and Type II Errors
Because a decision is made from a sample, it can be wrong in two ways.









\(H_0\) is true
\(H_0\) is false




Reject \(H_0\)
Type I error (\(\alpha\))
Correct decision (power)


Fail to reject \(H_0\)
Correct decision
Type II error (\(\beta\))



A Type I error is rejecting a true null hypothesis (a false positive); its probability is the significance level \(\alpha\). A Type II error is failing to reject a false null hypothesis (a false negative); its probability is \(\beta\). The power of a test, \(1 - \beta\), is the chance of correctly detecting a real effect. Lowering \(\alpha\) guards against false positives but makes false negatives more likely, so the choice of \(\alpha\) balances the two risks.


Try it The Type I / Type II tradeoff

A store’s average purchase has been $50. A marketing campaign may have raised it, so we test \(H_0: \mu \leq 50\) against \(H_a: \mu &gt; 50\) (with \(\sigma = \$20\)). The gray curve is where \(\bar{x}\) lands if the campaign did nothing; the colored curve is where it lands if the true mean really moved. Slide \(\alpha\) and watch \(\beta\) move the other way. Then try a bigger sample.

viewof eAlpha = Inputs.range([0.01, 0.30], {value: 0.05, step: 0.01, label: "Significance α"})
viewof eMu1 = Inputs.range([50.5, 60], {value: 54, step: 0.5, label: "True mean μ ($)"})
viewof eN = Inputs.range([5, 200], {value: 30, step: 1, label: "Sample size n"})























eMath = {
  function cdf(z) {
    const t = 1 / (1 + 0.3275911 * Math.abs(z) / Math.SQRT2);
    const y = 1 - (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t * Math.exp(-z * z / 2);
    return z &gt;= 0 ? 0.5 * (1 + y) : 0.5 * (1 - y);
  }
  function inv(p) { let lo = -10, hi = 10; for (let i = 0; i &lt; 80; i++) { const m = (lo + hi) / 2; if (cdf(m) &lt; p) lo = m; else hi = m; } return (lo + hi) / 2; }
  return {cdf, inv};
}
eMu0 = 50
eSigma = 20
eSE = eSigma / Math.sqrt(eN)
eCrit = eMu0 + eMath.inv(1 - eAlpha) * eSE
eBeta = eMath.cdf((eCrit - eMu1) / eSE)
ePower = 1 - eBeta
eDens = (x, m) =&gt; Math.exp(-0.5 * ((x - m) / eSE) ** 2) / (eSE * Math.sqrt(2 * Math.PI))
eLo = eMu0 - 4 * eSE
eHi = Math.max(eMu1, eMu0) + 4 * eSE
eGrid = d3.range(0, 401).map(i =&gt; eLo + i * (eHi - eLo) / 400)
eH0 = eGrid.map(x =&gt; ({x, y: eDens(x, eMu0)}))
eH1 = eGrid.map(x =&gt; ({x, y: eDens(x, eMu1)}))
eStyle = ({fontFamily: "Inter, sans-serif", fontSize: "12px", background: "transparent", color: "var(--bs-ink-2)"})
eYmax = 1.15 / (eSE * Math.sqrt(2 * Math.PI))











































































































Plot.plot({
  width: Math.max(300, width - 50), height: 270, marginLeft: 10, marginRight: 10, marginBottom: 38, style: eStyle,
  x: {domain: [eLo, eHi], label: "Sample mean x̄ ($) →", labelAnchor: "right", tickFormat: d =&gt; "$" + d.toFixed(0)},
  y: {axis: null, domain: [0, eYmax * 1.12]},
  marks: [
    Plot.areaY(eH1.filter(d =&gt; d.x &lt;= eCrit), {x: "x", y: "y", fill: "var(--bs-part)", fillOpacity: 0.35}),
    Plot.areaY(eH0.filter(d =&gt; d.x &gt;= eCrit), {x: "x", y: "y", fill: "#F59E0B", fillOpacity: 0.55}),
    Plot.lineY(eH0, {x: "x", y: "y", stroke: "var(--bs-ink-3)", strokeWidth: 2}),
    Plot.lineY(eH1, {x: "x", y: "y", stroke: "var(--bs-part)", strokeWidth: 2}),
    Plot.ruleX([eCrit], {stroke: "var(--bs-ink)", strokeWidth: 1.5, strokeDasharray: "4,3"}),
    Plot.text([eCrit], {x: d =&gt; d, y: eYmax * 1.08, text: d =&gt; "reject H₀ if x̄ &gt; $" + d.toFixed(2), fill: "var(--bs-ink)", fontWeight: 600, textAnchor: "start", dx: 4}),
    Plot.text([eMu0], {x: d =&gt; d, y: eYmax * 0.93, text: () =&gt; "if H₀ is true (μ = $50)", fill: "var(--bs-ink-2)", textAnchor: "end", dx: -6}),
    Plot.text([eMu1], {x: d =&gt; d, y: eYmax * 0.93, text: d =&gt; "if μ really is $" + d.toFixed(1), fill: "var(--bs-part)", textAnchor: "start", dx: 6}),
    Plot.ruleY([0], {stroke: "var(--bs-line)"})
  ]
})







